<?php
declare(strict_types=1);
$root=dirname(__DIR__);
spl_autoload_register(function(string $class)use($root){$p='App\\Extensions\\InteractionEngine\\System\\';if(str_starts_with($class,$p)){$f=$root.'/System/'.str_replace('\\','/',substr($class,strlen($p))).'.php';if(is_file($f))require_once$f;}});
use App\Extensions\InteractionEngine\System\Onboarding\OnboardingPlanCompiler;
use App\Extensions\InteractionEngine\System\Surfaces\SurfaceWizardPolicy;
$tests=[];$test=function($n,$f)use(&$tests){$tests[$n]=$f;};$assert=function($c,$m='assert'){if(!$c)throw new RuntimeException($m);};
$test('Apex Plumbing onboarding routes to multiple owners with activation last',function()use($assert){$keys=['company.name','business.verticals','availability.business_hours','catalogue.service_name','brand.social_links','customer.guest_checkout','booking.photo_evidence','email.connect.connection_status','ai.authority','activation.go_live'];$compiler=new OnboardingPlanCompiler($keys);$plan=$compiler->compile('42',['company.name'=>'Apex Plumbing','business.verticals'=>['plumbing'],'availability.business_hours'=>['mon'=>['07:00','18:00']],'catalogue.service_name'=>'Blocked drains','brand.social_links'=>['https://example.test/apex'],'customer.guest_checkout'=>true,'booking.photo_evidence'=>'required','email.connect.connection_status'=>['status'=>'connected','connection_reference'=>'conn-whatsapp-1'],'ai.authority'=>'approval_required','activation.go_live'=>'now'],'p1',['correlation_id'=>'corr']);$arr=$plan->toArray();$providers=array_values(array_unique(array_map(fn($a)=>$a['provider']??'', $arr['actions'])));foreach(['crm','builder','chatbot','connect','titan_ai'] as$p)$assert(in_array($p,$providers,true),"missing $p");$last=end($arr['actions']);$assert(($last['group']??'')==='activation','activation not last');$assert(($last['requires_approval']??false)===true,'activation requires approval');});
$test('four PWA surface policy is explicit',function()use($assert){$p=new SurfaceWizardPolicy();$assert($p->allows('hub','new_customer_v1'));$assert(!$p->allows('hub','field_home_services_onboarding_v1'));$assert($p->allows('go','complete_job_v1'));$assert($p->allows('command','create_job_v1'));$assert($p->allows('onboarding','field_home_services_onboarding_v1'));});
$test('onboarding compiler consumes question destination metadata',function()use($assert,$root){$source=(string)file_get_contents($root.'/System/Onboarding/OnboardingPlanCompiler.php');$assert(str_contains($source,'onboarding_group'),'compiler must use data-driven onboarding group metadata');$assert(str_contains($source,'destinations'),'compiler must use question destination provider/capability metadata');});
$f=0;foreach($tests as$n=>$fn){try{$fn();echo"PASS $n\n";}catch(Throwable$e){$f++;echo"FAIL $n: {$e->getMessage()}\n";}}if($f)exit(1);echo"\n".count($tests)." Phase 6 onboarding/platform tests passed\n";
